import io, tempfile

class Wrap:
    def __init__(self):
        self._f = tempfile.TemporaryFile()
    def write(self, b):
        return self._f.write(b)
    def flush(self):
        self._f.flush()
    def fileno(self):
        return self._f.fileno()
    def writable(self):
        return True
    def readable(self):
        return False
    def seekable(self):
        return False
    def close(self):
        self._f.close()
    def isatty(self):
        return False

w = Wrap()
t = io.TextIOWrapper(w, encoding='utf-8', mode='w')
t.write('hello\n')
t.flush()
import subprocess, sys
subprocess.run(['echo','foo'], stdout=w)
t.flush()
print('done')
w._f.seek(0)
print(w._f.read())
